  filterByMemory(gated, product, task, { ignoreUnreadable: opts.ignoreUnreadableMemory })

mutations.replace:
const pre = filterByMemory(merged, product, task,
                          { ignoreUnreadable: opts.ignoreUnreadableMemory })
const { filtered_recommended, filtered_contacted, memory_status } = pre
const kept = pre.kept.filter(passesFollowerGate)

mutations.find:
c.score = scoreCreator(c)
c.tier = tierOf(c)
c.tier_adjustments = []
const geo = applyGeoPenalty(c, market)
if (geo === 'drop') return false
if (geo === 'demote') {
  const from = c.tier
  c.tier = DEMOTE[c.tier]
  if (from !== c.tier) c.tier_adjustments.push({
    kind: 'audience_geo', from, to: c.tier,
    reason: `${market} 受众占比低于 30%`,
  })
}

